def comps(g,val):
 h,w=len(g),len(g[0]);s=set();res=[]
 for r in range(h):
  for c in range(w):
   if g[r][c]==val and (r,c) not in s:
    q=[(r,c)];s.add((r,c));
    for x,y in q:
     for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
      a,b=x+dx,y+dy
      if 0<=a<h and 0<=b<w and g[a][b]==val and (a,b) not in s:s.add((a,b));q.append((a,b))
    res.append(q)
 return res
